INSERT INTO tracks (id, slug, title, summary, weeks, default_start, highlights, sort_order) VALUES
(3, 'design', 'Senior designer interview prep', 'Four weeks to prepare for senior graphic, brand and UI design roles: design fundamentals, Adobe tools and Figma, print and book production, branding and banner ads, web and UI/UX, and design leadership.', 4, '2026-11-09', 'Senior design interviews test judgement more than software: why you chose a layout, a typeface or a trade-off, and how you defended it to a client.\nExpect a portfolio review: 2–3 deep case studies (problem → constraints → process → result) beat 20 pretty images.\nProduction knowledge separates seniors from juniors: bleed, CMYK and colour profiles, preflight, export specs, accessibility and developer handoff.\nBe fluent in the Adobe suite and Figma, and explain how you keep files organised and non-destructive so a whole team can work in them.\nLeadership questions — critique, mentoring, stakeholders, estimates, AI in the workflow — come up in every senior loop. Prepare real stories.', 3)
INSERT INTO sections (id, track_id, slug, title, code_prefix, description, sort_order) VALUES
(9, 3, 'fundamentals', 'Design fundamentals', 'DF', 'Typography, colour, layout and grids, hierarchy and the principles behind every brief.', 1),
(10, 3, 'tools', 'Adobe & Figma', 'AD', 'Photoshop, Illustrator, InDesign, Acrobat and Figma — workflows, file hygiene and automation.', 2),
(11, 3, 'print', 'Print, books & publishing', 'PR', 'Colour management, bleed, preflight, book layout, binding, finishes and working with printers.', 3),
(12, 3, 'branding', 'Branding, banners & ads', 'BR', 'Identity systems, guidelines, campaigns, packaging, display banners and social design.', 4),
(13, 3, 'web', 'Web & UI/UX design', 'UX', 'Responsive layout, design systems, accessibility, research, prototyping and developer handoff.', 5),
(14, 3, 'leadership', 'Senior designer & leadership', 'DL', 'Portfolio, briefs, estimates, critique, stakeholders, mentoring and AI in the design workflow.', 6)
INSERT INTO questions (id, section_id, code, topic, level, question, answer, tips, sort_order) VALUES
(233, 9, 'DF-01', 'Typography', 'Medium', 'How do you choose and pair typefaces for a project? Walk me through your process.', '• Start from the brand, audience, medium and content — a law firm\'s annual report, a children\'s book and a fintech app need different voices.\n• Check function first: legibility at the sizes used, language support (e.g. Devanagari or Cyrillic), available weights, screen rendering, and the licence (desktop, web, app, ebook).\n• Pair by contrast with a clear role — e.g. a serif for headings and a humanist sans for body — or use one superfamily with many weights.\n• Limit to two families and build a type scale with defined sizes, leading and tracking for each level.\n• Test with real content at real size: print a page, check it on a phone, look at long paragraphs and numbers.', 'Follow-up: what makes a typeface good for body text? (generous x-height, open counters, even texture). Mention licensing — it is often forgotten.', 1),
(234, 9, 'DF-02', 'Typography', 'Medium', 'What is the difference between kerning, tracking and leading? When do you adjust each?', '• Kerning is the space between specific letter pairs (AV, To, Ty) — adjust it by eye on logos, headlines and large display type.\n• Tracking is uniform spacing across a range of text — tighten slightly for big headlines, loosen for all caps, small caps and very small text.\n• Leading is the distance between baselines — body text usually sits around 120–145% of the type size, and longer lines need more.\n• Metrics kerning uses the font\'s built-in pairs; optical kerning is calculated from the shapes — useful for mixed or poorly kerned fonts.\n• Don\'t track body text to fix bad line breaks — edit the copy or adjust hyphenation and justification instead.', 'Show an example: a wordmark you kerned by hand and why.', 2),
(235, 9, 'DF-03', 'Colour', 'Medium', 'Why do colours look different on screen and in print, and how do you keep a brand colour consistent?', '• Screens emit light (RGB, additive) and have a larger gamut; print reflects light through ink on paper (CMYK, subtractive) with a smaller gamut that depends on the paper.\n• Paper changes the result: uncoated stock absorbs ink and looks duller than coated stock.\n• Define the colour for each medium — Pantone (coated and uncoated), CMYK build, RGB and HEX — and approve them on physical proofs.\n• Use colour management: a calibrated monitor, the printer\'s ICC profile, soft proofing, and hard proofs for critical jobs.\n• Record which value to use where in the brand guidelines.', 'Mention that a Pantone colour on screen is only an approximation — approve it from a printed swatch book.', 3),
(236, 9, 'DF-04', 'Grids', 'Hard', 'How do you use grids in a layout, and when do you break them?', '• Grids give consistency, speed and alignment across pages or screens: margins, columns, gutters, modules and a baseline grid.\n• Choose by content: a single column for long reading, multi-column or modular for magazines, catalogues and dashboards, 12 columns for responsive web.\n• The grid supports hierarchy — important items span more columns, related items share edges.\n• Break it on purpose for emphasis (a full-bleed image, a pull quote across two columns), while keeping enough on the grid so the break reads as intentional.\n• For responsive layouts, change the column count and spans per breakpoint rather than scaling everything down.', 'Bring a portfolio piece and explain its grid (columns, gutters, baseline) — it proves systematic thinking.', 4),
(237, 9, 'DF-05', 'Hierarchy', 'Medium', 'A client says their poster \"doesn\'t stand out\". How do you diagnose and fix the visual hierarchy?', '• Ask what the single most important message and action are, and where and from what distance the poster will be seen.\n• Do a squint or blur test: if everything has the same weight, nothing stands out.\n• Fix it with contrast: one dominant element (headline or image) much larger, fewer type sizes, stronger value contrast, more white space.\n• Group secondary details (date, venue, info) by proximity and alignment; move logos and sponsors to a quiet zone.\n• Check the context: competing posters, viewing distance (type size) and lighting.', 'Use the phrase \"first, second, third read\" — then show a before/after.', 5),
(238, 9, 'DF-06', 'Gestalt', 'Hard', 'Explain the Gestalt principles and give an example of each from your work.', '• Proximity: things close together read as a group — labels next to their fields, captions next to images.\n• Similarity: the same colour, shape or size reads as related — all links in one colour, all primary buttons in one style.\n• Continuity and closure: the eye follows lines and completes shapes — logos with implied shapes or negative-space arrows.\n• Figure–ground: separating subject from background — modals over a dimmed page, negative-space logos.\n• Common region: elements inside a shared boundary (cards, panels) belong together.', 'Have one logo example and one UI example ready for figure–ground and proximity.', 6),
(239, 9, 'DF-07', 'Design principles', 'Hard', 'How do you balance aesthetics and function when they conflict?', '• Go back to the objective: who it is for, what they must do or understand, and how success is measured.\n• Treat function and accessibility (legibility, contrast, clarity) as non-negotiable, and express the aesthetic within those limits.\n• Look for options that satisfy both — the conflict often comes from an early assumption (one layout, one image), not a real trade-off.\n• When unsure, test: a quick user test, an A/B test, or a printed proof at real size.\n• Explain the decision to stakeholders with the evidence and what was gained.', 'Tell a real story where a beautiful option lost to a clearer one — and what you learnt.', 7),
(240, 9, 'DF-08', 'Multilingual design', 'Expert', 'How would you adapt a design system for many languages and cultures?', '• Text expansion: German or Finnish copy can run 30% longer than English or more — design flexible containers and avoid fixed-width buttons and text inside images.\n• Scripts: choose type families that support every needed script (Latin, Devanagari, Arabic, CJK) with matching weights, and adjust line height for tall marks.\n• Right-to-left languages (Arabic, Hebrew): mirror layouts, directional icons and reading order.\n• Culture: meanings of colours, gestures, imagery and symbols; local formats for dates, currency, names and addresses.\n• Process: localisation-ready templates, pseudo-localisation tests and native-speaker reviewers.', 'If you have worked on Indian-language or right-to-left projects, describe the type choices you made.', 8),
(241, 10, 'AD-01', 'Photoshop', 'Medium', 'What does non-destructive editing mean in Photoshop, and how do you work that way?', '• The original pixels are never permanently changed, so every edit can be adjusted or undone later.\n• Adjustment layers (Curves, Levels, Hue/Saturation) instead of direct adjustments; layer masks instead of the eraser.\n• Smart Objects for scaling and Smart Filters (blur, sharpen) that stay editable; linked Smart Objects for shared assets.\n• Retouch on separate empty layers (Spot Healing with \"Sample All Layers\"); dodge & burn on a 50% grey layer set to Overlay or Soft Light.\n• Keep a layered master (PSD/PSB) and export flattened copies.', 'Follow-up: the trade-offs are bigger files and slower performance — mention linked Smart Objects and PSB for very large files.', 1),
(242, 10, 'AD-02', 'Photoshop masking', 'Hard', 'How would you cut out a model with complex hair for a campaign image?', '• Start with Select Subject or the Object Selection tool to get a base selection.\n• Refine in Select and Mask: Refine Hair and the Refine Edge brush, adjust the edge-detection radius, decontaminate colours, output to a layer mask.\n• Fix the mask by hand with soft brushes; for tough backgrounds, build a mask from a high-contrast channel copy with Levels.\n• Match the new background: colour, light direction, grain and blur; remove halos on the edges.\n• Stay non-destructive: mask on the original layer, adjustments clipped above it.', 'Mention checking the cut-out at 100% zoom on both dark and light backgrounds.', 2),
(243, 10, 'AD-03', 'Illustrator', 'Medium', 'Why should a logo be made in Illustrator rather than Photoshop? Which files do you deliver?', '• Logos must scale from a favicon to a billboard — vectors are resolution-independent, Photoshop is pixel-based.\n• Vectors keep clean edges, editable shapes and exact colours (global swatches, spot colours for print).\n• Deliver: AI/EPS/PDF (vector, print), SVG (web), transparent PNGs in several sizes, and colour versions (full colour, one colour, reversed, black).\n• Include CMYK and Pantone versions for print and RGB/HEX for screen; outline fonts in final files and record the font names.\n• Add a short usage guide: clear space, minimum size and don\'ts.', 'Bonus: mention one artboard per version and Export for Screens for batch output.', 3),
(244, 10, 'AD-04', 'Illustrator paths', 'Hard', 'How do you build clean vector artwork, and how do you clean up an Image Trace result?', '• Use as few anchor points as possible: anchors at the extremes of curves, handles horizontal or vertical where possible, handle lengths around a third of the segment.\n• Construct geometry from shapes with Shape Builder or Pathfinder for consistency; align icons to the pixel grid.\n• Image Trace: pick a suitable preset, reduce colours, tune paths, corners and noise, then Expand.\n• Clean up: Simplify, delete stray points, merge same-colour shapes, redraw key curves with the Pen or Curvature tool.\n• Check in Outline mode (Ctrl/Cmd+Y) for overlaps and open paths before delivery.', 'Mention Outline mode — it shows you check how artwork is built, not just how it looks.', 4),
(245, 10, 'AD-05', 'InDesign', 'Medium', 'How would you set up an InDesign document for a 200-page report so it stays consistent and easy to edit?', '• Document setup: correct trim, bleed, margins and columns, facing pages, and a baseline grid that matches the body leading.\n• Parent pages for each section layout, with running heads, automatic page numbers and section markers.\n• A full style system: paragraph styles based on one body style, character styles, object styles, table and cell styles — no local overrides.\n• Automation: a primary text frame with smart text reflow, an automatic table of contents, cross-references and numbered lists.\n• Split chapters with the Book panel if several people work on it; keep Preflight on and Package at the end.', 'Point out that with a proper style system you can restyle the whole document in minutes.', 5),
(246, 10, 'AD-06', 'InDesign automation', 'Expert', 'What are GREP styles and Data Merge in InDesign? Give practical uses.', '• GREP styles apply a character style automatically to text that matches a pattern inside a paragraph style — e.g. bold every price, keep \"Rs. 500\" together, style phone numbers.\n• GREP Find/Change does bulk clean-up: double spaces, straight to curly quotes, dashes, empty paragraphs.\n• Data Merge fills a template from a CSV/TXT file to create catalogue pages, name badges and certificates; image fields start with @ in the header.\n• For complex catalogues, combine Data Merge with object styles and scripts, or use a dedicated plugin.\n• Always proof the merged output: long names, missing images, overset text.', 'Have one GREP you have actually used ready, such as \\d+% for percentages or a no-break rule for units.', 6),
(247, 10, 'AD-07', 'PDF export', 'Hard', 'Which PDF settings do you use for print and for screen, and why?', '• Print: follow the printer\'s spec — usually PDF/X-4 (live transparency, ICC profiles) or PDF/X-1a (flattened, CMYK only, for older workflows), with bleed, crop marks, high-resolution images and embedded fonts.\n• Set the output intent to the printer\'s condition (e.g. Coated FOGRA39 or GRACoL).\n• Screen: sRGB, downsampled and compressed images, tags for accessibility, links and bookmarks.\n• Before sending, check Acrobat Output Preview (separations, ink coverage), run Preflight and review the font list.\n• Never send a \"Smallest File Size\" PDF to a printer.', 'Follow-up: PDF/X-1a vs PDF/X-4 = flattened CMYK vs live transparency with colour management.', 7),
(248, 10, 'AD-08', 'Figma components', 'Medium', 'How do you build a reusable Figma component that works at different screen sizes?', '• Use auto layout for padding, gaps and direction; set children to hug or fill so the component resizes with its content.\n• Create variants with properties (type, size, state) plus boolean, instance-swap and text properties for optional icons and labels.\n• Bind colour, spacing and radius to variables so themes and modes update everywhere.\n• Set min/max widths and test with long text, other languages and empty states.\n• Publish to the team library with documentation and usage notes.', 'Mention stress-testing components with real content (long labels, two lines, no icon).', 8),
(249, 10, 'AD-09', 'Tool choice', 'Medium', 'Photoshop, Illustrator, InDesign or Figma — how do you choose the right tool for a job?', '• Photoshop: raster images — photo editing, retouching, compositing, textures, mockups.\n• Illustrator: vector artwork — logos, icons, illustrations, infographics, packaging dielines.\n• InDesign: multi-page, text-heavy layouts — books, magazines, brochures, reports, catalogues — with strong typography and print output.\n• Figma: screens — websites, apps, design systems, prototypes and collaborative workshops.\n• Combine them (linked PSD/AI files in InDesign, SVGs from Illustrator in Figma) and choose by output, collaboration and who edits the file next.', 'Describe a project where you used three tools together and why.', 9),
(250, 10, 'AD-10', 'Automation', 'Hard', 'How have you used automation to speed up repetitive design work?', '• Photoshop Actions with Batch or Image Processor to resize, watermark and export hundreds of product photos.\n• Data-driven graphics: Photoshop/Illustrator variables and InDesign Data Merge for catalogues and certificates.\n• Templates with locked layouts and editable fields for marketing teams (InDesign, Figma, Adobe Express).\n• Scripts or plugins for renaming layers, exporting assets and generating size variations.\n• Measure the time saved and document the workflow so others can use it.', 'Give numbers, e.g. \"cut banner adaptation from 2 days to 3 hours\".', 10),
(251, 10, 'AD-11', 'Generative AI', 'Hard', 'How do you use generative AI features (e.g. Firefly, Generative Fill) responsibly in client work?', '• Good uses: extending backgrounds for new ratios, removing distractions, quick concept variations, mood boards.\n• Quality control: check hands, text, edges and perspective; match grain and lighting; retouch the result.\n• Rights and policy: follow the client\'s AI policy. Adobe says Firefly is trained on licensed and public-domain content and offers commercial-use terms — confirm the current terms for your plan, and avoid tools with unclear rights for final art.\n• Transparency: keep Content Credentials where required and tell the client which parts are AI-assisted.\n• Never upload confidential client material to tools that are not approved.', 'Show excitement about the speed but responsibility about rights and quality.', 11),
(252, 10, 'AD-12', 'File handoff', 'Medium', 'How do you prepare design files so another designer can continue the work?', '• Clear structure: named layers, artboards and pages; organised folders; dated version names.\n• Assets collected (InDesign/Illustrator Package), fonts listed with licence details, colour swatches named.\n• Remove unused layers, swatches and styles; don\'t flatten anything that may need editing.\n• Add a short README: specs, decisions, open items, and where the final exports are.\n• Use cloud libraries or shared Figma files so assets stay in sync.', 'Interviewers often ask \"What does a good file look like?\" — this is the answer.', 12),
(253, 11, 'PR-01', 'Bleed', 'Medium', 'What are bleed, trim and safe area? How much do you use?', '• Trim is the final cut size. Bleed is artwork extending past the trim (commonly 3 mm, or 0.125 in in the US) so no white edge appears if the cut shifts slightly.\n• The safe area keeps text and key elements inside the trim — often 3–5 mm, more for thick books and near the binding.\n• Set bleed in the document setup and export with \"Use Document Bleed Settings\" and crop marks if the printer wants them.\n• Large-format and some book printers ask for more bleed — always check the spec sheet.\n• Common mistakes: backgrounds stopping at the trim, image edges inside the bleed, text too close to the edge.', 'A quick answer plus \"I always confirm the printer\'s spec sheet\" is the senior version.', 1),
(254, 11, 'PR-02', 'RGB to CMYK', 'Hard', 'A client sends bright RGB images and a neon-green brand colour for a printed brochure. What do you do?', '• Explain early that some RGB colours are outside the CMYK gamut and will print duller — show a soft proof with the printer\'s profile.\n• Convert images to the right CMYK profile with a suitable rendering intent (perceptual, or relative colorimetric with black point compensation), then fine-tune with Curves.\n• For the brand colour, consider a Pantone spot or fluorescent ink as an extra colour if the budget allows; otherwise pick the closest CMYK build and approve it on a proof.\n• Ask for a hard proof of the colour-critical pages.\n• Document the decision so future materials match.', 'Stress managing the client\'s expectations before the job is printed — that is the senior skill.', 2),
(255, 11, 'PR-03', 'Rich black', 'Medium', 'What is rich black, and when should you (not) use it?', '• Rich black adds cyan, magenta and yellow under 100% K (e.g. C60 M40 Y40 K100) for a deeper black on large solid areas.\n• Use it for big backgrounds and large headlines; use 100% K only for small text and thin lines so they stay sharp even if plates shift slightly.\n• Keep total ink coverage within the printer\'s limit (often around 300% on coated stock, lower on uncoated).\n• Registration black (100% of every ink) is only for crop marks, never for artwork.\n• Ask the printer for their preferred rich-black recipe.', 'Follow-up: overprint means ink prints on top instead of knocking out — usually on for 100% K text.', 3),
(256, 11, 'PR-04', 'Preflight', 'Hard', 'Walk me through your preflight checklist before sending a job to print.', '• Document: correct trim size, page count and order, bleed set and used, safe margins respected.\n• Images: effective resolution of 300 ppi (or the spec), correct colour mode/profile, no missing or modified links.\n• Text: fonts available and licensed, no overset text, a final proofread and spell check.\n• Colour: no stray RGB or unwanted spot colours, rich black and total ink checked, overprint previewed, no hairlines under 0.25 pt.\n• Output: the right PDF standard, marks and file names; InDesign Preflight plus Acrobat Preflight/Output Preview; Package the job for the archive.', 'Say that you use a written checklist — mistakes in print cost real money.', 4),
(257, 11, 'PR-05', 'Book layout', 'Hard', 'How would you design and typeset a 300-page novel?', '• Agree the specs with the publisher and printer: trim size, paper, page count, binding (perfect bound), spine-width formula and print method.\n• Choose a typeface made for long reading (Garamond-, Minion- or Sabon-style), around 10–12 pt with comfortable leading and a measure of about 60–70 characters.\n• Set a larger gutter margin for the binding and a baseline grid so lines back up on both sides of the sheet.\n• Styles for body, first paragraphs (no indent), chapter openers on recto pages, running heads and page numbers; front and back matter in the right order.\n• Finish the typesetting (hyphenation and justification, widows, orphans, rivers), then design the cover as one spread with the final spine width.', 'Bonus: mention confirming the paper\'s thickness (PPI) with the printer to calculate the spine.', 5),
(258, 11, 'PR-06', 'Binding', 'Medium', 'What is the difference between saddle stitch, perfect binding and case binding, and how does each affect the design?', '• Saddle stitch: folded sheets stapled through the spine; pages in multiples of 4; best for thin booklets; creep pushes inner pages outward, so keep margins generous.\n• Perfect binding: pages glued into a cover with a flat spine you can design; the gutter swallows space, so widen inner margins and avoid key content across the spread.\n• Case binding (hardcover): boards wrapped in printed paper or cloth; the cover template needs wrap and turn-in allowances.\n• Wire-o/spiral: lies flat but needs a margin for the holes.\n• Always get the printer\'s cover template for spine and wrap sizes.', 'Mention creep in saddle-stitched booklets — it shows hands-on experience.', 6),
(259, 11, 'PR-07', 'Special finishes', 'Hard', 'How do you prepare artwork for spot UV, foil or embossing?', '• Each finish needs its own artwork: a separate layer filled with a 100% spot swatch (named e.g. \"SpotUV\" or \"Foil_Gold\"), set to overprint.\n• Keep it vector and exactly aligned with the CMYK artwork; avoid very thin lines and tiny text that will not reproduce.\n• Send a visual mock-up and check the separations in Acrobat Output Preview so the printer can see what goes where.\n• Confirm the finisher\'s minimum line weight, registration tolerance and file requirements.\n• Remember that finishes add setup cost and production days.', 'The key technical points: a clearly named spot swatch set to overprint, on its own layer.', 7),
(260, 11, 'PR-08', 'Paper', 'Medium', 'How does the choice of paper affect a print design?', '• Coated paper (gloss, silk, matte) gives sharper images and brighter colours; uncoated feels natural and premium but absorbs ink, so colours darken and detail softens.\n• Weight (gsm): flyers are often 130–170 gsm, covers and business cards 300–400 gsm; heavier paper changes spine width and postage.\n• Opacity: thin paper shows through — avoid heavy solids behind text on the other side.\n• Grain direction affects folding and cracking — score heavy stock before folding.\n• Ask for paper and printed samples, and pick colours from the matching swatch book (C or U).', 'Share a story where the paper changed the design (e.g. switching to uncoated for an eco brand).', 8),
(261, 11, 'PR-09', 'Printer issues', 'Medium', 'A job came back from the printer with the wrong colours and the client is upset. What do you do?', '• Stay calm and get the facts: compare the print with the approved proof under proper lighting, and check the PDF (profiles, RGB elements, overprint) against the spec.\n• If the file was at fault, own it, fix it and agree a reprint plan and cost.\n• If the press missed the approved contract proof, raise it with the printer with evidence — printers usually reprint in that case.\n• Update the client quickly with a clear plan and timeline.\n• Prevent a repeat: contract proofs, press checks for critical jobs and a better preflight checklist.', 'They are testing ownership and calm communication — structure it as facts → fix → prevent.', 9),
(262, 11, 'PR-10', 'Large format', 'Expert', 'How do you design for large-format print such as billboards, exhibition stands and vehicle wraps?', '• Get the exact spec: final size, bleed (often larger), working scale (many printers accept 1:10 or 1:4), resolution at final size, material and finishing (eyelets, pole pockets, hems).\n• Resolution depends on viewing distance: billboards need far fewer ppi at full size than an exhibition panel seen up close.\n• Design for distance and seconds: very large type, few words, high contrast, a simple composition.\n• Use vectors where possible; upscale photos carefully and check them at 100% at the final scale.\n• Physical context: panel seams (keep faces and text away), lighting, and vehicle doors and handles (work on the vehicle template).', 'Mention working at scale (e.g. 1:10) and planning around seams — practical details impress.', 10),
(263, 12, 'BR-01', 'Logo design', 'Medium', 'Walk me through how you design a logo, from brief to delivery.', '• Discovery: business goals, audience, competitors, values and where the logo will appear; mood boards.\n• Concepts: lots of black-and-white sketches first, narrowed to 3 strong directions with a rationale.\n• Refinement: geometry, lettering, small-size and one-colour tests, legibility, and checks that it is distinctive.\n• Present in context (signage, app icon, packaging, social) with the story behind the idea.\n• Deliver the full logo system with files and usage rules.', 'Mention testing at 16 px and in one colour — weak logos fail there.', 1),
(264, 12, 'BR-02', 'Brand guidelines', 'Hard', 'What goes into brand guidelines, and how do you make sure people actually follow them?', '• Core content: story and values, logo usage (versions, clear space, minimum size, don\'ts), colours with every value, typography, imagery and illustration style, icons, layout examples, tone of voice.\n• Practical tools: ready-made templates (social, presentations, ads, documents), a downloadable asset library and good-use examples.\n• Format: a living website or Figma library is easier to update than a PDF.\n• Adoption: onboarding sessions, a clear contact and approval process, regular audits of real materials.\n• Iterate: update the guidelines whenever teams keep working around them.', 'Senior angle: guidelines are a product for internal users — measure and improve them.', 2),
(265, 12, 'BR-03', 'Rebranding', 'Expert', 'How would you lead a rebrand for an established company without losing recognition?', '• Audit first: research what customers recognise and value (brand equity), list every touchpoint, review competitors.\n• Choose the scope from business strategy, not taste: evolution (refresh) or revolution (new identity).\n• Keep the recognisable assets — colour, shape, name style — where they carry equity, and modernise how they are used.\n• Test concepts with customers and stakeholders; plan the rollout by priority and budget (digital first, signage over time).\n• Govern the transition: guidelines, templates, training and a timeline for retiring old assets.', 'Use a well-known evolution-vs-revolution example, then your own project.', 3),
(266, 12, 'BR-04', 'Campaign adaptation', 'Hard', 'How do you take one campaign idea across print, outdoor, digital and social?', '• Lock the core: single-minded message, key visual, headline, CTA and brand elements.\n• Build master layouts with rules for crops, type sizes and logo placement in each ratio (landscape, square, portrait, vertical, banners).\n• Adapt to each channel: billboards — few words; social — motion and captions for sound-off; display — tiny sizes and a clear CTA; print — more detail.\n• Produce at scale with templates, linked assets and automation, and QA a sample of every format.\n• Measure results per channel and optimise the creative.', 'Show a campaign grid with every format on one page.', 4),
(267, 12, 'BR-05', 'Display banners', 'Medium', 'What are the most common display banner sizes, and what makes a banner effective?', '• Common sizes: 300×250, 728×90, 160×600, 300×600, 320×50 and 970×250.\n• Effective banners have one message, a clear brand, a visible CTA button, strong contrast and type that is readable at actual size.\n• Animation: tell the story in 2–3 frames within the network\'s limit (e.g. 30 seconds on Google Ads) and end on brand + offer + CTA.\n• Respect file-size limits and test on real pages and devices.\n• Design the whole set together so it reads as one campaign.', 'Mention that you design the end frame first — it is the one most people see.', 5),
(268, 12, 'BR-06', 'HTML5 banners', 'Hard', 'How do you produce HTML5 banners that meet ad network requirements?', '• Read the spec sheet first: sizes, maximum file size (initial and polite load), animation length, looping, border, clickTag and backup image.\n• Build in Google Web Designer or Adobe Animate, or hand-code HTML/CSS/JS with a light animation library.\n• Optimise: compressed images, SVG for shapes and logos, system or subset fonts, sprite sheets.\n• Implement the clickTag so the network can track clicks, and supply a static backup image.\n• Test in the network\'s validator or preview and on mobile.', 'Mention the backup image and the clickTag — both are often forgotten.', 6),
(269, 12, 'BR-07', 'Social design', 'Medium', 'How do you design social media content that performs well?', '• Start from the platform and format: sizes and safe zones (1:1, 4:5, 9:16), sound-off viewing, scrolling speed.\n• Hook people in the first second: a bold visual, faces, motion, short text.\n• Stay consistent with brand templates while allowing variety; build recognisable series.\n• Add captions, alt text and enough contrast for accessibility.\n• Use data — engagement, saves, shares, click-through — and test variations.', 'Quote a specific metric you improved.', 7),
(270, 12, 'BR-08', 'Packaging', 'Hard', 'What do you need to consider when designing packaging?', '• Structure: work on the printer\'s dieline (cut, fold and glue areas) and test with a physical mock-up.\n• Shelf impact: brand and product name visible from a distance, and a clear system for variants (colour coding by flavour or size).\n• Mandatory information: legal text, ingredients, nutrition, barcode (size and quiet zone), recycling marks — check the regional rules.\n• Print: the material (board, plastic, metal), finishes, spot colours, white ink on foil or clear film.\n• Production: proofs with the converter, colour checked on the real material, barcode scan tests.', 'Mention that you never edit the dieline itself — it sits on a locked layer.', 8),
(271, 12, 'BR-09', 'Logo critique', 'Expert', 'What makes a logo good? Critique a famous logo with those criteria.', '• Criteria: simple, memorable, distinctive in its category, right for the brand, works at every size and in one colour, lasting rather than trendy.\n• Craft: balanced geometry, good negative space, consistent stroke weights, well-spaced lettering.\n• System: works as a responsive set (full, compact, icon) alongside the brand\'s type and colour.\n• Structure the critique: purpose → what works → weaknesses → how you would improve it.\n• Example: the FedEx wordmark — plain type with an arrow hidden in the negative space suggests movement, and it works in one colour and at small sizes.', 'Prepare two logos: one you admire and one you would improve, with reasons.', 9),
(272, 12, 'BR-10', 'Brand governance', 'Expert', 'How do you keep a brand consistent when many teams and agencies create materials?', '• One source of truth: a guidelines site, Figma/Creative Cloud libraries, approved templates and a digital asset manager (DAM).\n• Make it easy: templates for the most common needs, and automation for resizing and localisation.\n• Governance: brand-team review for high-visibility work, self-serve for low-risk work, clear approval paths.\n• Education: onboarding for agencies, office hours, examples of good and bad use.\n• Audit real outputs regularly and fill template gaps.', 'Talk about balancing control with speed — teams bypass rules that slow them down.', 10),
(273, 13, 'UX-01', 'Responsive design', 'Medium', 'How do you design a website that works on mobile, tablet and desktop?', '• Mobile-first: prioritise content and actions for the smallest screen, then enhance for larger ones.\n• Set breakpoints from the content, and show layouts for key widths (e.g. 375, 768 and 1280+ px).\n• Use fluid grids, flexible images, a maximum content width and a responsive type scale.\n• Adapt components: navigation (menu button vs full bar), tables (stack or scroll), images (art-directed crops).\n• Prototype and test on real devices — touch targets and thumb reach matter on phones.', 'Show the same page at three widths in your portfolio.', 1),
(274, 13, 'UX-02', 'Design systems', 'Hard', 'How would you build a design system for a growing company?', '• Audit the current UI: inventory components, colours and type styles, and find inconsistencies and the most-used patterns.\n• Foundations first: tokens for colour, typography, spacing, radius and elevation, with accessibility built in.\n• Components by priority (buttons, inputs, navigation, cards, modals) with variants, states, documentation and matching code.\n• Partner with engineering: shared naming, Storybook or similar, versioning and release notes.\n• Governance and adoption: a contribution model, office hours and metrics (component coverage, time saved).', 'Show that you treat it as a product: users, roadmap, adoption metrics.', 2),
(275, 13, 'UX-03', 'Accessibility', 'Hard', 'How do you make your designs accessible? Name specific WCAG criteria.', '• Colour contrast: 4.5:1 for normal text, 3:1 for large text and for UI components and graphics (WCAG 2.2 AA).\n• Never rely on colour alone — add text labels, icons or patterns.\n• Visible focus indicators, a logical focus order and interactions that work with a keyboard.\n• Clear labels and instructions, helpful error messages, and targets of at least 24×24 CSS px.\n• Alt text for meaningful images, captions for video, support for reduced motion — and test with tools and real assistive technology.', 'Mention checking designs with a contrast plugin and doing a keyboard-only walk-through.', 3),
(276, 13, 'UX-04', 'UX process', 'Medium', 'Describe your UX design process from problem to launch.', '• Understand: stakeholder goals, user research, analytics, competitor review and constraints.\n• Define: a problem statement, success metrics, user flows and priorities.\n• Design: sketches, wireframes, prototypes and design-system components.\n• Validate: usability tests and iteration; check feasibility with developers.\n• Deliver and measure: handoff, design QA of the build, metrics after launch, then iterate.', 'Say that you scale the process to the size of the project — it sounds senior.', 4),
(277, 13, 'UX-05', 'Usability testing', 'Hard', 'How do you plan and run a usability test, and what do you do with the results?', '• Define the goals and questions, and pick tasks from the key user journeys.\n• Recruit about 5 representative users per round; run moderated (remote or in person) or unmoderated sessions.\n• Stay neutral: think-aloud, don\'t lead, watch behaviour more than opinions.\n• Analyse success rate, time on task, errors and quotes; group issues and rate their severity.\n• Share a short report with prioritised fixes and video clips, then iterate and retest.', 'Mention inviting developers and stakeholders to watch — it builds buy-in.', 5),
(278, 13, 'UX-06', 'Heuristics', 'Medium', 'What are Nielsen\'s usability heuristics? Apply two of them to a real interface.', '• The 10: visibility of system status; match with the real world; user control and freedom; consistency and standards; error prevention; recognition rather than recall; flexibility and efficiency; aesthetic and minimalist design; helping users recover from errors; help and documentation.\n• System status example: a file upload with a progress bar and a confirmation.\n• Error prevention example: inline validation that flags a problem before the user presses \"Pay\".\n• Use them for quick expert reviews, then confirm with real users.\n• Rate findings by severity to decide what to fix first.', 'Have a before/after example from your own work.', 6),
(279, 13, 'UX-07', 'Fidelity', 'Medium', 'When do you use wireframes, mockups and prototypes?', '• Wireframes: structure, content priority and flow — fast to change, good for early alignment.\n• Mockups: high-fidelity visuals — type, colour, imagery and final components.\n• Prototypes: interactive behaviour to test flows, transitions and micro-interactions.\n• Choose the fidelity based on the question you need answered and who will see it.\n• Stay lean: don\'t polish screens before the flow is validated.', 'Say which decision each artefact helped you make.', 7),
(280, 13, 'UX-08', 'Forms', 'Hard', 'How do you design a long form (e.g. a loan application) to reduce drop-off?', '• Ask only for what is needed; split it into logical steps with a progress indicator; save progress.\n• Labels above fields, clear help text, smart defaults and the right input types (numeric keyboard, date pickers).\n• Validate inline after the user leaves a field, with error messages that say how to fix the problem.\n• Reduce effort: autofill, address lookup, document upload from the phone camera.\n• Measure drop-off at each step and test changes.', 'Call out placeholder-only labels as an anti-pattern.', 8),
(281, 13, 'UX-09', 'Developer handoff', 'Medium', 'How do you hand designs over to developers and make sure the build matches?', '• Involve developers from the start: feasibility, component reuse and effort.\n• Provide specs in Dev Mode, tokens, component names that match the code, responsive rules, states and interactions.\n• Annotate edge cases, content limits and accessibility (focus order, labels, alt text).\n• Export assets properly: SVG icons, optimised images at the right sizes.\n• Review the build on staging and prioritise the fixes together.', 'Mention design QA — many designers stop at handoff.', 9),
(282, 13, 'UX-10', 'Measuring design', 'Expert', 'How do you measure the success of a design?', '• Tie it to goals: business metrics (conversion, revenue, retention) and user metrics (task success, time on task, satisfaction, errors).\n• Frameworks such as Google\'s HEART (Happiness, Engagement, Adoption, Retention, Task success), working from goals to signals to metrics.\n• Capture a baseline first, then run an A/B test or a before/after comparison where possible.\n• Add qualitative signals: support tickets, usability sessions, user feedback.\n• Share the results and lessons — including when a design didn\'t work.', 'Give one real number from your own work.', 10),
(283, 13, 'UX-11', 'Theming', 'Hard', 'How do you design light and dark themes, or several brands, with one system?', '• Use semantic tokens (surface, text, border, action) mapped to raw values per theme — Figma variables with modes.\n• Dark mode is not inverted colours: use dark greys rather than pure black, lower the saturation, and show elevation with lighter surfaces.\n• Check contrast in every theme; images and illustrations may need their own variants.\n• Test every component in every mode before release.\n• Document which tokens teams may use — never raw HEX values inside components.', 'Mention Figma variable modes — practical and current.', 11),
(284, 13, 'UX-12', 'Web performance', 'Expert', 'How can design decisions affect a website\'s performance and SEO?', '• Images: the right formats (SVG icons, WebP/AVIF photos), correct sizes, compression, lazy loading below the fold.\n• Fonts: fewer families and weights, variable fonts, system fonts for UI where acceptable.\n• Stability: reserve space for images and ads so the layout doesn\'t jump (CLS), and keep the main content quick to appear (LCP).\n• Avoid heavy video or animation above the fold without a reason, and respect reduced-motion settings.\n• Semantic structure — headings, meaningful link text, alt text — helps both SEO and accessibility.', 'Mention Core Web Vitals (LCP, CLS, INP) — it shows you understand the developer side.', 12),
(285, 14, 'DL-01', 'Portfolio', 'Medium', 'Walk me through the project in your portfolio you are most proud of.', '• Context: client or company, goal, audience, your role and the team.\n• Problem and constraints: budget, timeline, technical or print limits, stakeholders.\n• Process and key decisions: research, concepts, why you chose one direction, the trade-offs.\n• Result: a measurable outcome or clear impact, feedback, what shipped.\n• Reflection: what you would do differently.', 'Use STAR (Situation, Task, Action, Result) and keep it to 5–7 minutes.', 1),
(286, 14, 'DL-02', 'Feedback', 'Medium', 'How do you handle negative feedback from a client or creative director?', '• Listen fully and ask questions to find the real concern.\n• Separate the problem from the suggested fix, and agree on what success looks like.\n• Respond with options and a rationale; push back with evidence when a change would hurt the goal.\n• Write down the agreed changes and next steps.\n• Don\'t take it personally — feedback improves the work.', 'Give an example where feedback made the work better.', 2),
(287, 14, 'DL-03', 'Stakeholder conflict', 'Hard', 'Marketing and product want opposite things in the same design. How do you resolve it?', '• Bring both sides together and restate the shared goal and each side\'s concerns.\n• Use evidence: user research, data, brand guidelines, competitor examples.\n• Explore options that satisfy both, and prototype quickly so the discussion is concrete.\n• Propose a test (A/B or usability) when data is missing.\n• If needed, escalate with a clear recommendation and its trade-offs.', 'Show facilitation, not winning.', 3),
(288, 14, 'DL-04', 'Deadlines', 'Medium', 'How do you handle a tight deadline while running several projects?', '• Clarify priorities with stakeholders and agree what \"done\" means for each project.\n• Break the work into tasks, estimate them and plan around fixed dates (print slots, launches).\n• Reduce scope smartly: fewer concepts, reused templates, automated production.\n• Warn people early if a timeline is at risk, and offer options.\n• Protect quality where it matters most (e.g. print accuracy).', 'Describe a real crunch and what you cut.', 4),
(289, 14, 'DL-05', 'Mentoring', 'Hard', 'How do you mentor junior designers?', '• Set clear expectations and growth goals, and hold regular one-to-ones.\n• Pair on real projects; review their files and process, not just the final visuals.\n• Give specific, actionable feedback tied to the goal, and say what works.\n• Delegate meaningful pieces with clear briefs and steadily more responsibility.\n• Share knowledge: templates, checklists, critique sessions, recommended resources.', 'Describe one person you mentored and how they grew.', 5),
(290, 14, 'DL-06', 'Running critiques', 'Hard', 'How do you run an effective design critique?', '• Set the stage: context, goal, stage of the work and the specific feedback needed.\n• Ground rules: critique the work against the brief, not the person; questions before solutions.\n• Structure: presenter shows the work → silent review and notes → round of feedback → discussion → decisions and next steps.\n• Facilitate: bring in quiet voices, keep to time, park off-topic points.\n• Follow up with notes and owners.', 'Mention asking \"What do you want feedback on?\" at the start.', 6),
(291, 14, 'DL-07', 'Estimating', 'Medium', 'How do you estimate the time and cost of a design project?', '• Clarify the scope and deliverables, including revision rounds, formats and approvals.\n• Break it into phases and tasks, use past projects as a reference, and add a 10–20% buffer.\n• Separate fixed costs (stock images, fonts, printing) from design time.\n• State assumptions and what is out of scope, and agree how change requests are handled.\n• Track actual time to improve future estimates.', 'Show a sample estimate breakdown.', 7),
(292, 14, 'DL-08', 'Vague briefs', 'Medium', 'What do you do when a brief is vague?', '• Ask about the objective, audience, message, deliverables, constraints, budget, timeline, approvers and success measures.\n• Write a short creative brief back and get agreement.\n• Run a quick discovery: mood boards, references, competitor review.\n• Show early low-fidelity directions to align before investing time.\n• Keep a record of decisions.', 'A senior turns a vague request into a clear brief — that is the answer.', 8),
(293, 14, 'DL-09', 'Raising quality', 'Expert', 'How do you raise design quality across a team?', '• Define standards: design principles, checklists (print, accessibility, handoff) and a definition of done.\n• Shared tools: libraries, templates, naming conventions and file structures.\n• Regular critiques and reviews, and senior–junior pairing.\n• Measure and share wins: customer outcomes, fewer errors, time saved.\n• Advocate for design in the business, so designers join projects at the planning stage.', 'Give an example of a checklist or template you introduced.', 9),
(294, 14, 'DL-10', 'AI in design', 'Hard', 'How is AI changing graphic and UI design, and how do you use it?', '• Speed: ideation, mood boards, variations, background extension, resizing, draft copy, research summaries.\n• Tools: Adobe Firefly and Generative Fill, Figma\'s AI features, image generators, AI-assisted research and transcription.\n• What stays human: understanding the brief and audience, the concept, taste, brand consistency, final craft and accountability.\n• Risks: copyright and licensing, generic-looking work, biased imagery, confidentiality and client policies; disclose AI use where needed.\n• Team approach: approved tools, a clear policy and review of AI-assisted output.', 'Be balanced: enthusiastic about productivity, clear about judgement and ethics.', 10),
(295, 14, 'DL-11', 'Failure', 'Medium', 'Tell me about a design project that failed. What did you learn?', '• Pick a real project: what happened, your role and the impact.\n• Analyse the causes honestly: unclear brief, missed constraint, poor communication, production error.\n• Show ownership: what you did to fix or limit the damage.\n• Share the lessons and what you changed: checklists, earlier proofs, better kickoff questions.\n• Keep it constructive — don\'t blame others.', 'Interviewers want self-awareness — the lesson matters more than the failure.', 11),
(296, 14, 'DL-12', 'Seniority', 'Expert', 'What makes a designer \"senior\", and why are you ready?', '• Owns outcomes end to end: from a vague brief to delivered, printed or shipped work.\n• Strong judgement: picks the right problem, direction and trade-offs, and explains decisions clearly.\n• Production excellence: files, specs, accessibility, printing and handoff without errors.\n• Multiplies others: mentors, builds systems and templates, improves the process.\n• Partners with the business: understands goals and metrics, manages stakeholders and budgets.', 'Back each point with a short example from your career.', 12)
INSERT INTO notes (id, track_id, code, group_name, topic, body, example, remember, sort_order) VALUES
(105, 3, 'DF-N01', 'Graphic design', 'Typography essentials', '• Anatomy: baseline, x-height, cap height, ascenders and descenders. The x-height decides how big a font looks at the same point size.\n• Classification: serif (old-style, transitional, modern/didone, slab), sans serif (grotesque, neo-grotesque, humanist, geometric), script, display, monospace.\n• Spacing: tracking (a whole range), kerning (letter pairs), leading (line spacing, often 120–145% of the size for body text) and measure (about 45–75 characters per line for comfortable reading).\n• Pairing: contrast with a clear role (e.g. serif headings + sans body) or one superfamily with many weights. Two families are usually enough.\n• Legibility = telling characters apart; readability = how easily long text is read (size, measure, leading, contrast).', 'Body: 10/14 pt Minion Pro, measure ~65 characters\nH1: 32/36 pt Inter SemiBold, tracking −10\nCaption: 8/11 pt, tracking +20', 'Talk in specs (size/leading, measure, tracking) — it signals real production experience.', 1),
(106, 3, 'DF-N02', 'Graphic design', 'Colour theory & colour models', '• Models: RGB (additive, screens), CMYK (subtractive, print), HSB/HSL (how designers think about colour), LAB (device-independent, used for conversions).\n• Harmonies: complementary, analogous, triadic, split-complementary — then tints, shades and tones to build a working palette.\n• Value (lightness) carries hierarchy and accessibility more than hue — check every design in greyscale.\n• Gamut: many vivid RGB colours (bright greens, blues, oranges) cannot be printed in CMYK. Spot colours (Pantone) or extended-gamut printing cover what CMYK cannot.\n• Colour meaning depends on culture and category (red = sale, danger or luck depending on the market) — research the audience.', 'Brand teal: HEX #0E5E6F · RGB 14/94/111\nCMYK: converted with the printer\'s profile and approved on a proof\nPantone: chosen from a printed swatch book, not the screen', 'Always specify colour for every medium: HEX/RGB for screen, CMYK and Pantone for print.', 2),
(107, 3, 'DF-N03', 'Graphic design', 'Layout, grids & white space', '• Grids: manuscript (single column), column grids (12 columns on the web, 6–12 for editorial), modular grids, and baseline grids for vertical rhythm.\n• Margins, gutters and a consistent spacing scale (4/8 px on screen; mm or pt multiples in print) create rhythm.\n• White space is active: it groups related items (proximity) and gives the focal point room to breathe.\n• Alignment: one strong edge beats many centred elements. Breaking the grid on purpose creates emphasis.\n• Responsive grids change the number of columns per breakpoint instead of shrinking everything.', 'A4 brochure: 6 columns, 4 mm gutter, 15 mm outer margin, 12 pt baseline grid\nWeb: 12 columns, 24 px gutter, max width 1200 px, 8 px spacing scale', 'Explain your grid in portfolio reviews — it proves the layout was designed, not just arranged.', 3),
(108, 3, 'DF-N04', 'Graphic design', 'Visual hierarchy & Gestalt', '• Hierarchy tools: size, weight, colour/value contrast, position, white space — and motion on screen.\n• Gestalt principles: proximity, similarity, continuity, closure, figure–ground, common region.\n• Reading patterns: Z-pattern for sparse layouts (posters, hero sections), F-pattern for text-heavy pages.\n• One primary focal point per view; secondary and tertiary levels support it.\n• Squint or blur test: the order you notice things should match the order of the message.', 'Poster read order: 1) headline 2) key visual 3) date and venue 4) logo and sponsors — sized roughly in that order', 'Hierarchy answers \"what should the viewer see first, second and third?\" — say that sentence in interviews.', 4),
(109, 3, 'DF-N05', 'Graphic design', 'Design principles & critique language', '• Core principles: contrast, balance (symmetric/asymmetric), alignment, repetition, proximity, emphasis, scale and unity.\n• Critique against the goal — \"Does it meet the brief for this audience?\" — before \"Do I like it?\".\n• Useful phrases: \"The CTA competes with the headline\", \"The type scale has too many steps\", \"This crop loses the subject\'s eyeline\".\n• Constraints are part of the design: budget, timeline, print process, platform specs and brand rules.\n• Accessibility is a principle, not a final check: contrast, size and clarity help everyone.', 'Feedback formula: what works → what could be stronger and why (tied to the goal) → a suggestion or a question', 'Seniors critique against the brief and the audience, never personal taste.', 5),
(110, 3, 'AD-N01', 'Adobe & Figma', 'Photoshop non-destructive editing', '• Work non-destructively: adjustment layers, layer masks, Smart Objects with Smart Filters, and retouching on separate layers.\n• Selections: Select Subject / Object Selection, then Select and Mask for hair; output to a layer mask instead of deleting pixels.\n• Retouching: Spot Healing, Healing Brush and Clone Stamp; frequency separation for skin; dodge & burn on a 50% grey layer set to Overlay or Soft Light.\n• Generative Fill / Generative Expand (Firefly) speed up extensions and clean-up — check quality, licence terms and the client\'s AI policy.\n• Edit in RGB (often 16-bit for heavy grading) and convert to CMYK late with the printer\'s profile; 300 ppi at the final print size.', 'Layer stack: Background (locked) → Retouch (Spot Healing, \"Sample All Layers\") → Curves (masked) → product as Smart Object with a Gaussian Blur Smart Filter', 'Say that you never destroy original pixels — it shows you build team-friendly files.', 6),
(111, 3, 'AD-N02', 'Adobe & Figma', 'Illustrator vector craft', '• Vectors scale without quality loss — use them for logos, icons, illustrations and anything that must be resized.\n• Pen and Curvature tools for clean paths with few anchor points; Shape Builder and Pathfinder to construct shapes; Image Trace for quick conversions (then clean up).\n• Global swatches and graphic/character styles keep brand colours and type editable everywhere at once.\n• The Appearance panel stacks fills, strokes and effects on one object and keeps them editable; Expand only when output requires it.\n• Multiple artboards for logo versions and sizes; Export for Screens / Asset Export for SVG and PNG sets; outline or package fonts for print.', 'Logo file: artboards for full colour, one colour, reversed and icon-only; global swatch named \"Brand Teal (Pantone ref)\"', 'Clean geometry (few anchors, icons aligned to the pixel grid) is the craft signal interviewers look for.', 7),
(112, 3, 'AD-N03', 'Adobe & Figma', 'InDesign long documents & styles', '• Paragraph, character, object, table and cell styles — everything styled, nothing formatted locally. Nested and GREP styles automate rules (e.g. bold every price).\n• Parent pages (formerly master pages) hold running heads, page numbers and grids; a primary text frame lets text flow automatically.\n• Long documents: Book panel (.indb) to combine chapters, automatic table of contents from paragraph styles, cross-references, footnotes and an index.\n• A baseline grid plus \"align to baseline grid\" keeps columns and facing pages in line.\n• Data Merge for catalogues, certificates and badges; the Preflight panel checks errors live; Package collects fonts and links for the printer.', 'Styles: Body (10/14, align to baseline), H1 (based on Body, 24/28, keep with next), Caption (8/11)\nGREP style: \\d+% → character style \"Bold\"', 'If you can explain parent pages, styles and Package, you sound like someone who has shipped real books.', 8),
(113, 3, 'AD-N04', 'Adobe & Figma', 'Acrobat & PDF workflows', '• Export the right PDF: PDF/X-4 (keeps live transparency and ICC profiles) or PDF/X-1a (flattened, CMYK only) for print; a smaller, interactive PDF for screen.\n• Acrobat Pro: Output Preview (separations, total ink coverage), Preflight profiles, comments for client review, Compare Files.\n• Accessible PDFs: tags, reading order, alt text and document language — start in InDesign (tagged PDF export), finish in Acrobat.\n• Review cycles: shared review links, comment summaries and dated version names — never \"final_final_v3.pdf\".\n• Before sending, remove hidden layers and metadata; PDF passwords and permissions are weak protection.', 'Print export: PDF/X-4, printer\'s output profile (e.g. Coated FOGRA39), 3 mm bleed, crop marks offset 3 mm', 'Name the PDF standard the printer asked for — guessing is a junior mistake.', 9),
(114, 3, 'AD-N05', 'Adobe & Figma', 'Figma for designers', '• Auto layout (padding, gap, hug/fill/fixed) builds responsive components; constraints handle absolutely positioned layers.\n• Components and variants with properties form a library; instances keep their overrides when the main component changes.\n• Variables and modes hold colour, spacing and type tokens for light/dark themes or multiple brands.\n• Collaboration: comments, branching for big changes, Dev Mode for developer specs, named versions at milestones.\n• Prototyping: interactions, Smart Animate and flows for usability tests; FigJam for workshops and journey maps.', 'Button component: Type = Primary | Secondary | Ghost × Size = S | M | L × State = Default | Hover | Disabled\nColours bound to variables like color/action/primary', 'Figma is the default UI tool today (Adobe XD is in maintenance mode) — be fluent in libraries and auto layout.', 10),
(115, 3, 'AD-N06', 'Adobe & Figma', 'File organisation, automation & handoff', '• Naming: client_project_item_version_date (e.g. acme_brochure_A4_v03_2026-11-04); layers and artboards named — never \"Layer 47\".\n• Link large assets instead of embedding them; Creative Cloud Libraries share colours, type styles and graphics across apps.\n• Automation: Photoshop Actions + Batch / Image Processor, InDesign Data Merge and scripts, Illustrator variables, export presets.\n• Versioning: dated versions or cloud version history; keep one master file and export copies.\n• Handoff: font licences checked, links packaged, export specs written down — a stranger should be able to open and finish your file.', 'Folders: 01_Brief  02_Research  03_Working  04_Assets (linked)  05_Exports  06_Final_Print', 'Seniors are judged on whether other people can work in their files.', 11),
(116, 3, 'PR-N01', 'Print design', 'Colour management for print', '• RGB on screen becomes CMYK on paper and colours shift. Manage it with ICC profiles that match the press and paper (e.g. FOGRA39/FOGRA51 for coated stock in Europe, GRACoL/SWOP in the US, Japan Color) — ask the printer which one.\n• Rendering intents: relative colorimetric (keeps in-gamut colours accurate) vs perceptual (compresses the whole range — good for photos with many out-of-gamut colours).\n• Soft proof on a calibrated monitor (View → Proof Setup); use a hard/contract proof for colour-critical work.\n• Spot colours (Pantone) give exact brand colour or special effects (metallic, fluorescent); CMYK builds of spot colours always shift a little.\n• Coated and uncoated paper change the same ink: uncoated looks duller and darker — pick swatches for the real stock (C vs U).', 'Brand red: the Pantone \"C\" swatch for coated stock, the matching \"U\" swatch for uncoated\nCMYK build: taken from Pantone\'s official colour bridge guide, approved on a printed proof', '\"Which profile and paper are we printing on?\" is the first question a senior asks the printer.', 12),
(117, 3, 'PR-N02', 'Print design', 'Print file setup: bleed, margins & resolution', '• Bleed: extend backgrounds and images past the trim — usually 3 mm (0.125 in in the US); some book and large-format printers ask for more.\n• Safe area: keep text and logos 3–5 mm inside the trim, and more near the spine of perfect-bound books.\n• Resolution: 300 ppi effective at final size for photos; raster line art 600–1200 ppi; large format viewed from far away can be much lower.\n• Black: rich black (e.g. C60 M40 Y40 K100) for large solid areas; 100% K only for small text so it stays sharp. Keep total ink coverage inside the printer\'s limit (often around 300% on coated stock, lower on uncoated).\n• Fonts embedded or outlined, images in the right colour mode, transparency handled (PDF/X-4), overprint checked in Output Preview.', 'A5 flyer: document 148 × 210 mm, 3 mm bleed on all sides (exports at 154 × 216 mm), 5 mm safe margin, images 300 ppi at placed size', 'Bleed, safe area, 300 ppi, rich black, ink limit — say all five and you pass the print-basics round.', 13),
(118, 3, 'PR-N03', 'Print design', 'Book design & typesetting', '• Structure: front matter (half title, title page, copyright, contents), body, back matter (notes, index). Recto = right-hand, odd pages; verso = left-hand, even pages.\n• Trim sizes depend on genre (e.g. 5.5 × 8.5 in or 6 × 9 in trade paperbacks); inner (gutter) margins are larger for perfect binding.\n• Typesetting: consistent text block on a baseline grid, sensible hyphenation and justification; fix widows, orphans, rivers and bad breaks.\n• Spine width depends on page count and paper thickness — the printer supplies the formula. The cover is designed as one spread: back + spine + front + bleed.\n• Ebooks: reflowable EPUB (text first, styles matter) vs fixed layout (picture books, cookbooks) — test on real devices.', 'Novel: 6 × 9 in, 11/15 pt Garamond, inner margin 22 mm, outer 16 mm\nChapters open on a recto page; 320 pages → spine width from the printer\'s formula', 'Mention widows and orphans, gutter margins and spine maths — interviewers will know you have done real books.', 14),
(119, 3, 'PR-N04', 'Print design', 'Binding, finishing & paper', '• Binding: saddle stitch (stapled, pages in multiples of 4, thin booklets, watch for creep), perfect binding (glued spine), case binding (hardcover), wire-o/spiral (lies flat), PUR (stronger glue).\n• Signatures: large sheets carry many pages and are folded (often 16 or 32 pages each) — page counts that fit signatures save money.\n• Finishes: matte, gloss or soft-touch lamination, spot UV, foil, embossing/debossing, die-cutting — each needs its own vector artwork layer.\n• Paper: weight (gsm), coated vs uncoated, opacity (show-through) and grain direction (affects folding and binding).\n• Imposition (arranging pages on the press sheet) is normally done by the printer — supply single pages with bleed unless told otherwise.', 'Spot UV layer: separate artwork filled with a 100% spot swatch named \"SpotUV\", set to overprint, aligned exactly with the CMYK artwork', 'Always ask \"How will it be bound and finished?\" before you design the layout.', 15),
(120, 3, 'PR-N05', 'Print design', 'Preflight & working with printers', '• Get the specs first: size, bleed, colour profile, PDF standard, ink limit, binding, finishing, delivery method and deadline.\n• Preflight with InDesign\'s Preflight panel and Acrobat Preflight/Output Preview: missing fonts, RGB images, low resolution, overset text, missing bleed, hairlines thinner than 0.25 pt.\n• Proofs: PDF proofs for content, hard/contract proofs for colour, a press check for critical jobs.\n• Package the job (fonts, links, IDML and PDF) for handover and archiving.\n• Talk to the printer early — a 10-minute call is cheaper than a reprint.', 'Printer checklist: A4 · 3 mm bleed · PDF/X-4 · FOGRA39 · TAC 300% · crop marks · no RGB · fonts embedded · job_pages_01-32.pdf', 'Seniors own the job until it is printed correctly, not until the file is sent.', 16),
(121, 3, 'BR-N01', 'Branding & advertising', 'Brand identity systems', '• An identity is logo + colour + typography + imagery + graphic elements + tone of voice, used consistently at every touchpoint.\n• Logo types: wordmark, lettermark, symbol, combination mark, emblem. Plan a responsive set (full, compact, icon) for small spaces.\n• Logo rules: clear space, minimum size (mm for print, px for screen), approved colour versions (full, one colour, reversed) and clear don\'ts.\n• Brand architecture: branded house (one master brand), house of brands, or endorsed brands.\n• Process: discovery → positioning → concepts → refinement → system → guidelines → rollout.', 'Logo set: horizontal, stacked, icon\nClear space = height of the \"x\" in the wordmark; minimum width 25 mm / 120 px', 'A logo is not a brand — talk about the whole system and how it scales.', 17),
(122, 3, 'BR-N02', 'Branding & advertising', 'Brand guidelines', '• Contents: story and values, logo usage, colour palette with HEX/RGB/CMYK/Pantone, typography hierarchy, imagery and illustration style, icons, layout examples, tone of voice and templates.\n• Make them practical: do/don\'t examples, ready-made templates (social, presentations, ads) and downloadable assets.\n• Living guidelines (a website or a Figma library) are easier to keep current than a static PDF.\n• Governance: who approves new uses, how requests are handled and how often the guidelines are reviewed.\n• Measure adoption by auditing real materials, then fix the gaps with better templates.', 'Colour page: Primary Teal — HEX #0E5E6F, RGB 14/94/111, CMYK and Pantone references\nUsage: about 60% neutrals, 30% primary, 10% accent', 'Guidelines succeed when they make the right thing the easy thing — templates beat rules.', 18),
(123, 3, 'BR-N03', 'Branding & advertising', 'Advertising & campaign design', '• Start from the brief: objective, audience, single-minded message, call to action, mandatory elements, channels and KPIs.\n• A key visual (KV) and headline system that adapts across print, outdoor, digital, social and in-store.\n• Outdoor and billboards are seen for seconds: very few words, huge type, high contrast, a visible logo.\n• Adaptation at scale: master layouts with rules for each ratio (1:1, 4:5, 9:16, 16:9, banner sizes), plus templates and automation for hundreds of versions.\n• Legal and compliance: claims backed up, minimum size for disclaimers, licences for images, fonts and music.', 'Campaign kit: KV master (16:9) → A4 print, billboard, 1080×1080, 1080×1350, 1080×1920, 300×250, 728×90, 160×600', 'Show that you can design a system that survives 50 adaptations, not just one hero layout.', 19),
(124, 3, 'BR-N04', 'Branding & advertising', 'Display & HTML5 banner production', '• Common IAB sizes: 300×250 (medium rectangle), 728×90 (leaderboard), 160×600 (wide skyscraper), 300×600 (half page), 320×50 (mobile leaderboard), 970×250 (billboard).\n• Hierarchy for tiny spaces: logo, short message, clear CTA button. Every frame must work alone, and the last frame repeats the brand and CTA.\n• Formats: static (JPG/PNG/GIF) or HTML5 (Google Web Designer, Adobe Animate or hand-coded). Respect each network\'s file-size and animation limits (e.g. Google Ads allows at most 30 seconds of animation).\n• Keep files small: optimised images, SVG/CSS for shapes, subset fonts. Many networks cap the initial load at around 150 KB — check the spec sheet.\n• Implement the clickTag, add a border if the background is white, and check legibility at actual size on a phone.', '300×250 storyboard: F1 product + headline (0–3 s) → F2 benefit (3–6 s) → F3 offer + CTA + logo (6–9 s); loop twice, stop on F3', 'Mention clickTag, file-size limits and the end frame — it shows real banner production experience.', 20),
(125, 3, 'BR-N05', 'Branding & advertising', 'Social media design', '• Sizes: 1080×1080 (1:1), 1080×1350 (4:5 portrait feed), 1080×1920 (9:16 stories/reels — keep text out of the top and bottom areas covered by the app\'s UI), 1920×1080 (16:9 video).\n• Stop the scroll: strong first frame, faces, motion and bold contrast; design for sound-off viewing with captions.\n• Templates (Figma, Photoshop, Adobe Express) let marketing teams create on-brand posts quickly.\n• Test creative by changing one thing at a time (image, headline or CTA) and read click-through and conversion, not just likes.\n• Accessibility: alt text, captions, enough contrast, and as little text baked into images as possible.', 'Story layout: 1080×1920 canvas, key text in the central area, CTA kept clear of the bottom UI zone', 'Talk about results (CTR, conversion) as well as looks — senior designers measure their work.', 21),
(126, 3, 'UX-N01', 'UI/UX design', 'Responsive web layout', '• Mobile-first: design the smallest layout first, then add columns and detail as space grows.\n• Breakpoints follow the content; common ranges are ~360–480 px (phones), 768 px (tablets), 1024–1280 px (laptops), 1440 px+ (desktops).\n• Fluid grids, a maximum content width, flexible images and type that scales with the viewport.\n• Touch targets at least 24×24 CSS px (WCAG 2.2 AA minimum); 44–48 px is more comfortable to tap.\n• Performance is design: SVG for icons, WebP/AVIF for photos, lazy-loaded media, fewer font files (variable fonts).', 'Card grid: 1 column under 600 px, 2 columns from 600 px, 3 columns from 1024 px; max width 1200 px, 24 px gutters', 'Describe how a layout changes at each breakpoint — not just \"it shrinks\".', 22),
(127, 3, 'UX-N02', 'UI/UX design', 'UI design systems', '• Layers: design tokens (colour, type, spacing, radius, shadow) → components (button, input, card) → patterns (forms, navigation) → templates and pages.\n• Name tokens by purpose (\"color/text/primary\"), not by value (\"blue-500\"), so themes and dark mode can change values safely.\n• Each component documents its states (default, hover, focus, active, disabled, error, loading), sizes, content rules and accessibility notes.\n• A Figma library plus matching coded components (e.g. in Storybook) — the system is only real when design and code agree.\n• Governance: contribution process, versioning, changelog and deprecation of old components.', 'Token: color/background/surface = #FFFFFF (light) / #121212 (dark)\nSpacing scale: 4, 8, 12, 16, 24, 32, 48', 'Treat a design system as a product with users (designers and developers), not a sticker sheet.', 23),
(128, 3, 'UX-N03', 'UI/UX design', 'Accessibility (WCAG) for designers', '• Contrast (WCAG 2.2 AA): 4.5:1 for normal text; 3:1 for large text (24 px, or 18.66 px bold) and for UI components and meaningful graphics.\n• Never use colour alone to carry meaning (errors, charts, links) — add icons, text or patterns.\n• Visible focus states, logical reading and tab order, real labels (not placeholder-only) and error messages that explain the fix.\n• Targets at least 24×24 CSS px, motion that can be reduced, captions and transcripts for media.\n• Test with a contrast checker, a keyboard-only pass, a screen-reader spot check (VoiceOver/NVDA) and 200% zoom.', '#767676 on white = 4.54:1 → passes AA for body text\n#999999 on white = 2.85:1 → fails', 'Name the numbers (4.5:1, 3:1, 24 px) — accessibility knowledge is expected of seniors.', 24),
(129, 3, 'UX-N04', 'UI/UX design', 'UX research & usability', '• Methods: interviews, surveys, analytics, usability tests (moderated or unmoderated), card sorting, tree testing, A/B tests.\n• About five users per round find most usability problems (Nielsen) — test small and often.\n• Nielsen\'s 10 heuristics: system status, match with the real world, user control, consistency, error prevention, recognition over recall, flexibility, minimalist design, error recovery, help.\n• Outputs: personas or jobs-to-be-done, journey maps, problem statements, prioritised findings.\n• Combine qualitative evidence (why) with quantitative evidence (how many) before big decisions.', 'Test plan: goal · 5 participants · 4 tasks (\"find and book a delivery slot\") · success rate, time on task, quotes · top 5 issues with severity', 'Seniors bring evidence to design debates instead of opinions.', 25),
(130, 3, 'UX-N05', 'UI/UX design', 'Wireframes, prototypes & interaction design', '• Fidelity ladder: sketches → low-fidelity wireframes (structure) → high-fidelity mockups (visuals) → interactive prototypes (behaviour).\n• Pick fidelity for the question: low-fi to test flow and content, high-fi to test visual clarity and micro-interactions.\n• Interaction details: states, feedback, transitions (100–300 ms feels responsive), and empty, loading and error states.\n• Microcopy is design: verbs on buttons, helpful error text, consistent terms.\n• Present prototypes with the scenario and the decision you need — not just a row of screens.', 'Checkout prototype: cart → address → payment → confirmation, plus a declined-card error state and an empty-cart state', 'Designing the unhappy paths (errors, empty states) is what separates senior work.', 26),
(131, 3, 'UX-N06', 'UI/UX design', 'Developer handoff & collaboration', '• Involve developers early: technical limits, component reuse and effort estimates shape the design.\n• Handoff: Dev Mode specs, tokens, component names that match the code, responsive behaviour, interactions and exported assets (SVG icons, optimised images).\n• Annotate accessibility (focus order, labels, alt text), edge cases and content limits (long names, translations).\n• QA the build: review it on staging, prioritise visual bugs, pair with the developer to fix them quickly.\n• Use the same names for components and tokens in Figma and in code.', 'Annotation: \"Title truncates after 2 lines with an ellipsis; full text in a tooltip. Focus order: search → filters → results.\"', 'Handoff is a conversation, not a file drop.', 27),
(132, 3, 'DL-N01', 'Design leadership', 'Portfolio & case studies for senior roles', '• 3–5 deep case studies beat many thumbnails. Each covers: context, problem, your role, constraints, process, key decisions, result, and what you would change.\n• Show your thinking: sketches, rejected options and why, research insights, iterations.\n• Quantify outcomes where you can: sales lift, CTR, time saved, print cost reduced, adoption of a system.\n• Order the case studies for the role (brand, print, or product/UI).\n• Practise a 30–45 minute walkthrough with a clear story and timing.', 'Case-study outline (example): brand refresh for a 40-store retailer → my role: lead designer, team of 3 → constraint: 8 weeks, existing signage → result: guidelines + 120 templates, lower rollout cost', 'Interviewers hire your decisions and impact, not your mockups.', 28),
(133, 3, 'DL-N02', 'Design leadership', 'Briefs, estimates & project management', '• A good brief has: objective, audience, message, deliverables and specs, mandatory elements, budget, timeline, approvers and success measures.\n• Clarify before designing: ask questions, write the creative brief back to the client and agree the scope.\n• Estimate by task (research, concepts, revision rounds, production, proofs) with a buffer, and agree the number of revision rounds.\n• Manage scope creep: log changes, explain the impact on time and cost, get approval.\n• Rhythm: kickoff → concepts → feedback → refinement → final artwork → proof → delivery, with weekly status updates.', 'Estimate: discovery 4 h · 3 concepts 12 h · 2 revision rounds 8 h · artwork for 6 formats 10 h · proofs and printer liaison 4 h = 38 h + 15% buffer', 'Seniors protect quality by managing scope, time and expectations.', 29),
(134, 3, 'DL-N03', 'Design leadership', 'Critique, feedback & stakeholders', '• Run critiques with a purpose: share the context and the question, collect feedback against the brief, agree next steps.\n• When receiving feedback, separate the problem from the suggested fix — ask \"What are you worried about?\".\n• Presenting to clients: start with the objective, explain the rationale, show 2–3 strong options (not 10) and recommend one.\n• Disagreements: bring evidence (research, tests, data, brand rules), propose an experiment, and escalate respectfully if needed.\n• Build trust with regular updates and no surprises.', '\"I hear the logo should be bigger. Is the worry that people won\'t recognise the brand? We could test brand recall with 5 people before changing the layout.\"', 'Turn \"make the logo bigger\" into a conversation about the real goal.', 30),
(135, 3, 'DL-N04', 'Design leadership', 'Mentoring, design ops & AI in the workflow', '• Mentoring: pair on real work, review files (not just visuals), give specific feedback, delegate with clear briefs.\n• Design ops: templates, libraries, naming conventions, folder structures, review checklists, tool licences, onboarding docs.\n• A definition of done: specs met, accessibility checked, preflighted, files packaged.\n• AI tools (Firefly, Generative Fill, Figma\'s AI features, image generators) speed up ideation, variations, clean-up and resizing; people still own the concept, taste and final quality.\n• Risks: copyright and licensing, client policies, brand consistency, disclosure (Content Credentials), and confidential work in unapproved tools.', 'Team AI policy: allowed for mood boards and image extensions; final artwork reviewed by a designer; client approval required; Content Credentials kept on exports', 'Present AI as a tool you govern — speed with judgement — not a replacement for design thinking.', 31)
