-- PrepHub: "Senior designer interview prep" track. Safe to re-run: rows are upserted by id.
SET NAMES utf8mb4;

ON DUPLICATE KEY UPDATE slug = VALUES(slug), title = VALUES(title), summary = VALUES(summary), weeks = VALUES(weeks), default_start = VALUES(default_start), highlights = VALUES(highlights), sort_order = VALUES(sort_order);

ON DUPLICATE KEY UPDATE track_id = VALUES(track_id), slug = VALUES(slug), title = VALUES(title), code_prefix = VALUES(code_prefix), description = VALUES(description), sort_order = VALUES(sort_order);

ON DUPLICATE KEY UPDATE section_id = VALUES(section_id), code = VALUES(code), topic = VALUES(topic), level = VALUES(level), question = VALUES(question), answer = VALUES(answer), tips = VALUES(tips), sort_order = VALUES(sort_order);

ON DUPLICATE KEY UPDATE track_id = VALUES(track_id), code = VALUES(code), group_name = VALUES(group_name), topic = VALUES(topic), body = VALUES(body), example = VALUES(example), remember = VALUES(remember), sort_order = VALUES(sort_order);

ON DUPLICATE KEY UPDATE track_id = VALUES(track_id), day_number = VALUES(day_number), week = VALUES(week), week_theme = VALUES(week_theme), focus = VALUES(focus), notes_refs = VALUES(notes_refs), qa_refs = VALUES(qa_refs), practice = VALUES(practice), planned_hours = VALUES(planned_hours);
